16	    static void callback(void * arg, int status, int, struct hostent * host)
17	    {
18	        auto * ptr_records = reinterpret_cast<std::vector<std::string>*>(arg);
19	        if (status == ARES_SUCCESS && host->h_aliases)
20	        {
21	            int i = 0;
22	            while (auto * ptr_record = host->h_aliases[i])
23	            {
24	                ptr_records->emplace_back(ptr_record);
