32	    CaresPTRResolver::CaresPTRResolver(CaresPTRResolver::provider_token) : channel(nullptr)
33	    {
34	        /*
35	         * ares_library_init is not thread safe. Currently, the only other usage of c-ares seems to be in grpc.
36	         * In grpc, ares_library_init seems to be called only in Windows.
37	         * See https://github.com/grpc/grpc/blob/master/src/core/ext/filters/client_channel/resolver/dns/c_ares/grpc_ares_wrapper.cc#L1187
38	         * That means it's safe to init it here, but we should be cautious when introducing new code that depends on c-ares and even updates
39	         * to grpc. As discussed in https://github.com/ClickHouse/ClickHouse/pull/37827#discussion_r919189085, c-ares should be adapted to be atomic
40	         * */
41	        if (ares_library_init(ARES_LIB_INIT_ALL) != ARES_SUCCESS || ares_init(&channel) != ARES_SUCCESS)
42	        {
43	            throw DB::Exception("Failed to initialize c-ares", DB::ErrorCodes::DNS_ERROR);
44	        }
45	    }
